/**
 * مركز الواتساب — توجيه التنبيهات حسب الصفحة
 *
 * الأنظمة ما تكتب اسم الكروب. ترسل {page:'اسم الصفحة', topic:'returns', text, group:'الكروب القديم'}
 * والمركز يوصّلها لكل كروب/رقم بالدليل مربوط بهالصفحة ومأشّر عليه هالنظام (عمود «التنبيهات»).
 * وكل تنبيه صفحة تنرسل منه نسخة لكل مستلم مأشّر عليه «نسخة كل التنبيهات» (واتس اب المشرفات).
 * تنبيه بدون صفحة (مثل تقرير المشرفات) يروح لكل مستلم مأشّر عليه هالنظام.
 * تنبيه لصفحة ما إلها مستلم ← ينسجّل بـ «غير موجّهة» (والنسخة توصل للمشرفات حتى ما يضيع).
 */

const TOPICS = [
  { key: 'msgs', label: 'رسائل الزبائن', hint: 'التعليقات والرسائل المتأخرة وخمول الصفحة', core: true },
  { key: 'arabon', label: 'العربونات', hint: 'عربونات متأخرة عن الاستلام', core: true },
  { key: 'returns', label: 'الرواجع والقطع', hint: 'تأخير تحديث الرواجع + رسالة القطع', core: true },
  { key: 'postponed', label: 'المؤجل', hint: 'تذكير الفواتير المؤجلة', core: true },
  { key: 'schedule', label: 'انتهاء الجدولة', hint: 'تذكير قبل ما تخلص جدولة المنشورات', core: true },
  { key: 'sup_report', label: 'تقرير المشرفات', hint: 'صورة جدول الصفحات 9 الصبح و9 بالليل', core: false },
  { key: 'copy_all', label: 'نسخة كل التنبيهات', hint: 'نسخة من كل تنبيه يروح لأي صفحة', core: false },
];
const TOPIC_BY_KEY = {}, TOPIC_BY_LABEL = {};
TOPICS.forEach(t => { TOPIC_BY_KEY[t.key] = t; TOPIC_BY_LABEL[t.label] = t; });

const SH_PAGES = 'الصفحات', SH_GROUPS = 'كروبات الواتساب', SH_UNROUTED = 'غير موجّهة';
const HEAD_PAGES = ['الصفحة', 'الكروب القديم', 'المصدر', 'آخر تحديث'];
const HEAD_GROUPS = ['اسم الكروب بالواتساب', 'أول مرة', 'آخر فحص'];
const HEAD_UNROUTED = ['الصفحة', 'النظام', 'عدد المرات', 'آخر مرة', 'آخر نص'];
const DIR_PAGE_COL = 8, DIR_TOPICS_COL = 9;   // H «الصفحة»، I «التنبيهات»

const SUPA = {
  URL: 'https://lxikqgjfjnfkhvuckihx.supabase.co',
  KEY: 'sb_publishable_9AKXuA_fvfQroYZDRDpRfQ_bYXfrxoT',
};

// نفس الاسم بكتابات مختلفة: «لمسة أناقة» = «لمسة اناقة»، «حياة أسهل » = «حياة اسهل»
function normPage_(s) {
  return String(s || '').trim().toLowerCase()
    .replace(/[أإآٱ]/g, 'ا').replace(/ة/g, 'ه').replace(/ى/g, 'ي').replace(/ؤ/g, 'و').replace(/ئ/g, 'ي')
    .replace(/[ً-ْـ]/g, '').replace(/[\s\-_.]+/g, '');
}
function topicsFromCell_(v) {
  return String(v || '').split(/[,،]/).map(s => s.trim()).filter(Boolean)
    .map(s => (TOPIC_BY_LABEL[s] || TOPIC_BY_KEY[s] || {}).key).filter(Boolean);
}
function topicsToCell_(keys) { return (keys || []).map(k => (TOPIC_BY_KEY[k] || {}).label).filter(Boolean).join('، '); }

function routeSheet_(name, head) {
  const ss = SpreadsheetApp.getActive();
  let sh = ss.getSheetByName(name);
  if (!sh) {
    sh = ss.insertSheet(name);
    sh.getRange(1, 1, 1, head.length).setValues([head]).setFontWeight('bold').setBackground('#1f3a5f').setFontColor('#ffffff');
    sh.setFrozenRows(1); sh.setRightToLeft(true);
  }
  return sh;
}
function ensureDirRouteCols_() {
  const dir = SpreadsheetApp.getActive().getSheetByName(SH.DIR);
  if (String(dir.getRange(1, DIR_PAGE_COL).getValue()) !== 'الصفحة')
    dir.getRange(1, DIR_PAGE_COL, 1, 2).setValues([['الصفحة', 'التنبيهات']]).setFontWeight('bold').setBackground('#1f3a5f').setFontColor('#ffffff');
}

/* ---------- مستلمي كل صفحة/نظام ---------- */
function loadRoutes_() {
  const sh = SpreadsheetApp.getActive().getSheetByName(SH.DIR);
  const n = sh.getLastRow() - 1;
  const out = [];
  if (n < 1) return out;
  sh.getRange(2, 1, n, DIR_TOPICS_COL).getValues().forEach(r => {
    const name = String(r[0]).trim();
    if (!name || String(r[4]).trim() === 'لا') return;
    const type = String(r[1]).indexOf('جروب') > -1 ? 'جروب' : 'شخص';
    const raw = String(r[2]).trim();
    out.push({ name, type, target: type === 'شخص' ? normPhone_(raw) : raw, sender: String(r[3]).trim(),
      page: String(r[DIR_PAGE_COL - 1] || '').trim(), pageKey: normPage_(r[DIR_PAGE_COL - 1]), topics: topicsFromCell_(r[DIR_TOPICS_COL - 1]) });
  });
  return out;
}

// m: {page, topic, text, file, group}  → [{entry, text}]  + unrouted?
function resolveRoute_(m, routes, now) {
  const topic = String(m.topic || '').trim();
  if (!TOPIC_BY_KEY[topic]) throw new Error('نظام تنبيه غير معروف: ' + topic);
  const page = String(m.page || '').trim(), pk = normPage_(page);
  const out = [];
  const direct = routes.filter(r => r.topics.indexOf(topic) > -1 && (page ? r.pageKey === pk : true));
  direct.forEach(r => out.push({ entry: r, text: String(m.text || '') }));
  if (page && topic !== 'copy_all') {
    const head = ['📋 *نسخة — صفحة ' + page + '*' + (m.group ? '  (كروب ' + String(m.group).trim() + ')' : ''),
      '🗓 ' + ['الأحد', 'الاثنين', 'الثلاثاء', 'الأربعاء', 'الخميس', 'الجمعة', 'السبت'][Number(Utilities.formatDate(now, 'Asia/Baghdad', 'u')) % 7] + ' ' +
      Utilities.formatDate(now, 'Asia/Baghdad', 'd/M h:mm a').replace('AM', 'ص').replace('PM', 'م') +
      (direct.length ? '' : '  ⚠️ ما انرسلت للصفحة: ما إلها كروب بالدليل'), '━━━━━━━━━━━━━━', ''].join('\n');
    routes.filter(r => r.topics.indexOf('copy_all') > -1 && direct.indexOf(r) < 0)
      .forEach(r => out.push({ entry: r, text: head + String(m.text || '') }));
  }
  return { targets: out, unrouted: !direct.length };
}

function noteUnrouted_(page, topic, text, now) {
  const sh = routeSheet_(SH_UNROUTED, HEAD_UNROUTED);
  const v = sh.getDataRange().getValues(), label = (TOPIC_BY_KEY[topic] || {}).label || topic;
  for (let i = 1; i < v.length; i++) {
    if (normPage_(v[i][0]) === normPage_(page) && v[i][1] === label) {
      sh.getRange(i + 1, 3, 1, 3).setValues([[Number(v[i][2] || 0) + 1, now, String(text).slice(0, 300)]]);
      return;
    }
  }
  sh.appendRow([page || '(بدون صفحة)', label, 1, now, String(text).slice(0, 300)]);
}

/* ---------- قائمة الصفحات ---------- */
// من نظام المراقبة (Supabase) + أي صفحة وصل إلها تنبيه (مثل صفحات نظام التحديثات)
function syncPages_() {
  const sh = routeSheet_(SH_PAGES, HEAD_PAGES);
  const v = sh.getDataRange().getValues();
  const have = {}; for (let i = 1; i < v.length; i++) have[normPage_(v[i][0])] = i + 1;
  const r = UrlFetchApp.fetch(SUPA.URL + '/rest/v1/rpc/hub_pages', { method: 'post', contentType: 'application/json', payload: '{}',
    headers: { apikey: SUPA.KEY, Authorization: 'Bearer ' + SUPA.KEY }, muteHttpExceptions: true });
  if (r.getResponseCode() !== 200) throw new Error('قائمة الصفحات من نظام المراقبة: ' + r.getResponseCode() + ' ' + r.getContentText().slice(0, 200));
  const now = new Date(), add = [];
  JSON.parse(r.getContentText()).forEach(p => {
    const k = normPage_(p.name); if (!k) return;
    if (have[k]) sh.getRange(have[k], 2, 1, 3).setValues([[p.wa_group || '', 'المراقبة', now]]);
    else { add.push([p.name, p.wa_group || '', 'المراقبة', now]); have[k] = -1; }
  });
  if (add.length) sh.getRange(sh.getLastRow() + 1, 1, add.length, HEAD_PAGES.length).setValues(add);
}
function rememberPage_(page, group) {
  if (!page) return;
  const sh = routeSheet_(SH_PAGES, HEAD_PAGES);
  const v = sh.getDataRange().getValues(), k = normPage_(page);
  for (let i = 1; i < v.length; i++) if (normPage_(v[i][0]) === k) { if (!v[i][1] && group) sh.getRange(i + 1, 2).setValue(group); return; }
  sh.appendRow([page, group || '', 'تنبيه', new Date()]);
}

