function requestScan_(by) {
  const q = SpreadsheetApp.getActive().getSheetByName(SH.QUEUE), now = new Date();
  const v = q.getLastRow() > 1 ? q.getRange(2, 1, q.getLastRow() - 1, HEAD.QUEUE.length).getValues() : [];
  if (v.some(r => r[Q.TYPE] === 'فحص' && (r[Q.STATUS] === ST.PENDING || r[Q.STATUS] === ST.SENDING) && now - new Date(r[Q.TIME]) < 15 * 60000))
    return 'طلب الفحص موجود بالانتظار';
  const id = 'S' + Utilities.formatDate(now, 'Asia/Baghdad', 'yyMMddHHmmss');
  q.appendRow([id, now, 'لوحة: ' + by, 'اكتشاف الكروبات', 'فحص', 'groups', 'scan', '', ST.PENDING, 0, '', '', '']);
  return 'ok';
}
