  if (!sender) return { ok: false, error: 'جهاز غير معروف' };
  const sh = routeSheet_(SH_GROUPS, HEAD_GROUPS), now = new Date();
  const v = sh.getDataRange().getValues(), have = {};
  for (let i = 1; i < v.length; i++) have[String(v[i][0]).trim()] = i + 1;
  const add = [];
  [].concat(b.groups || []).map(g => String(g || '').trim()).filter(Boolean).forEach(g => {
    if (have[g]) sh.getRange(have[g], 3).setValue(now); else { add.push([g, now, now]); have[g] = -1; }
  });
  if (add.length) sh.getRange(sh.getLastRow() + 1, 1, add.length, 3).setValues(add);
  if (b.id) report_({ device: b.device, id: b.id, ok: true });
  return { ok: true, added: add.length };
}
function readGroups_() {
  const sh = routeSheet_(SH_GROUPS, HEAD_GROUPS), n = sh.getLastRow() - 1;
  if (n < 1) return [];
  return sh.getRange(2, 1, n, 3).getValues().filter(r => r[0]).map(r => ({ name: String(r[0]).trim(), first: r[1] ? new Date(r[1]).getTime() : 0, last: r[2] ? new Date(r[2]).getTime() : 0 }));
}
function readPages_() {
  const sh = routeSheet_(SH_PAGES, HEAD_PAGES), n = sh.getLastRow() - 1;
  const pages = n < 1 ? [] : sh.getRange(2, 1, n, 3).getValues().filter(r => r[0]).map(r => ({ name: String(r[0]).trim(), key: normPage_(r[0]), group: String(r[1] || '').trim(), source: r[2] }));
  const un = routeSheet_(SH_UNROUTED, HEAD_UNROUTED), m = un.getLastRow() - 1;
  const unrouted = m < 1 ? [] : un.getRange(2, 1, m, 5).getValues().filter(r => r[0]).map(r => ({ page: String(r[0]), key: normPage_(r[0]), topic: r[1], count: r[2], last: r[3] ? new Date(r[3]).getTime() : 0 }));
  return { pages, unrouted };
}
